import{_ as t}from"./chunks/100.Bym1HttY.js";import{_ as n,o,c as a,ak as r}from"./chunks/framework.Ba6sv-31.js";const i="/projects/AiBlockSensor/en/latest/assets/1.DBTPDdWP.webp",l="/projects/AiBlockSensor/en/latest/assets/0.l6zlXCBQ.webp",s="/projects/AiBlockSensor/en/latest/assets/2.CnQAMt8P.webp",c="/projects/AiBlockSensor/en/latest/assets/3.Dz-1Ju-W.webp",h="/projects/AiBlockSensor/en/latest/assets/4.BTnbgNtq.webp",d="/projects/AiBlockSensor/en/latest/assets/5.BwkAIrIL.webp",y=JSON.parse('{"title":"10. 6-Channel Line Follower Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/10. 6-Channel Line Follower Sensor.md","filePath":"docs/10. 6-Channel Line Follower Sensor.md"}'),p={name:"docs/10. 6-Channel Line Follower Sensor.md"};function g(m,e,u,b,_,f){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_10-6-channel-line-follower-sensor" tabindex="-1">10. 6-Channel Line Follower Sensor <a class="header-anchor" href="#_10-6-channel-line-follower-sensor" aria-label="Permalink to &quot;10. 6-Channel Line Follower Sensor&quot;">​</a></h1><h2 id="_10-1-introduction" tabindex="-1">10.1 Introduction <a class="header-anchor" href="#_10-1-introduction" aria-label="Permalink to &quot;10.1 Introduction&quot;">​</a></h2><p>By comparing signals across its six optical sensors, the 6-channel line follower sensor accurately determines travel direction and deviation angle. This enables fast, reliable tracking on complex courses, including navigating sharp turns and detecting intersections, significantly improving robot performance.</p><img loading="lazy" height="558" width="1704" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_10-2-technical-specifications" tabindex="-1">10.2 Technical Specifications <a class="header-anchor" href="#_10-2-technical-specifications" aria-label="Permalink to &quot;10.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Calibration method</td><td style="text-align:center;">One-click calibration</td></tr><tr><td style="text-align:center;">Effective range</td><td style="text-align:center;">8 ~ 16 mm</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">87.5 × 23.5 × 13.0 mm</td></tr></tbody></table><h2 id="_10-3-calibration-method" tabindex="-1">10.3 Calibration Method <a class="header-anchor" href="#_10-3-calibration-method" aria-label="Permalink to &quot;10.3 Calibration Method&quot;">​</a></h2><p>Calibrate the 6-channel line follower sensor to the background and the black line using the <strong>calibration button</strong>. Follow the steps below to complete the calibration:</p><img loading="lazy" height="525" width="1480" src="'+l+'" class="common_img" style="width:500px;"><ol><li><p><strong>Background calibration:</strong> Hold the sensor over the background and long-press the <strong>calibration button</strong> until indicators 1 and 6 start flashing.</p></li><li><p><strong>Line calibration:</strong> Once all six indicators are flashing, move the sensor over the black line and press the <strong>calibration button</strong>.</p></li><li><p><strong>Completion:</strong> The center indicators will flash, and then all six indicators will turn solid, confirming that calibration is complete.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>During operation, keep probe ground clearance between 8 and 16 mm. When a probe detects the black line, its corresponding indicator lights up.</strong></p></div><h2 id="_10-4-hands-on-project" tabindex="-1">10.4 Hands-On Project <a class="header-anchor" href="#_10-4-hands-on-project" aria-label="Permalink to &quot;10.4 Hands-On Project&quot;">​</a></h2><h3 id="_10-4-1-project-introduction" tabindex="-1">10.4.1 Project Introduction <a class="header-anchor" href="#_10-4-1-project-introduction" aria-label="Permalink to &quot;10.4.1 Project Introduction&quot;">​</a></h3><p>This project uses the 6-channel line follower sensor to check whether each probe detects the black line and print the detected channel numbers to the serial port. Moving the sensor across the track displays real-time readings in the serial monitor, demonstrating how multi-channel line tracking works.</p><h3 id="_10-4-2-hardware-wiring" tabindex="-1">10.4.2 Hardware Wiring <a class="header-anchor" href="#_10-4-2-hardware-wiring" aria-label="Permalink to &quot;10.4.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the 6-channel line follower sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="771" width="1914" src="'+s+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among A, B, C, or D on the controller. Ensure that the port selected in the program matches the physical wiring.</strong></p></div><h3 id="_10-4-3-adding-extensions" tabindex="-1">10.4.3 Adding Extensions <a class="header-anchor" href="#_10-4-3-adding-extensions" aria-label="Permalink to &quot;10.4.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>6 Line follow sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+c+'" class="common_img" style="width:800px;"><h3 id="_10-4-4-complete-program-and-analysis" tabindex="-1">10.4.4 Complete Program and Analysis <a class="header-anchor" href="#_10-4-4-complete-program-and-analysis" aria-label="Permalink to &quot;10.4.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon start-up, initialize the 6-channel line follower sensor on port A.</p></li><li><p>Inside the main program loop, check channels 1 through 6 in order to see if each detects the black line.</p></li><li><p>When a channel detects the black line, print the channel number to the serial port.</p></li><li><p>Add a 0.1-second wait to refresh data quickly and track probe states in real time.</p></li></ol><img loading="lazy" height="801" width="547" src="'+h+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1fLfLXEVjSMZdojOq7C44xJqZIBm4MDem?usp=sharing" target="_blank" rel="noreferrer">Program Files/ 10 6-Channel Line Follower Sensor.sb3</a>.</strong></p></div><h3 id="_10-4-5-program-upload" tabindex="-1">10.4.5 Program Upload <a class="header-anchor" href="#_10-4-5-program-upload" aria-label="Permalink to &quot;10.4.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_10-4-6-program-outcome" tabindex="-1">10.4.6 Program Outcome <a class="header-anchor" href="#_10-4-6-program-outcome" aria-label="Permalink to &quot;10.4.6 Program Outcome&quot;">​</a></h3><p>Once the program is uploaded, check the serial monitor in the lower-right corner of the software. Moving a probe over the black line displays its corresponding channel number. If multiple probes detect the line simultaneously, their channel numbers appear in sequence, clearly indicating which probes are over the track.</p><img loading="lazy" height="952" width="1220" src="'+d+'" class="common_img" style="width:800px;">',31)])])}const x=n(p,[["render",g]]);export{y as __pageData,x as default};
